/* ============================================================
   HISTORY OF WORLD CUP — real_rosters.js
   Loturi reale (jucători reali istorici, nu generați) pentru toate
   combinațiile echipă+an care au participat cu adevărat la turneul
   respectiv (din cele 23 de echipe curate din TEAMS, data.js),
   plus câteva echipe "shadow" (adversari istorici reali în cele 12
   campanii curate din real_fixtures.js). Cheie: "<COD_ECHIPA>_<AN>".
   Fiecare jucător: { name, pos } — pos e una din GK/DF/MF/FW.

   Combinațiile echipă+an fără lot real aici (selectabile teoretic
   în joc, dar care nu au avut loc istoric) folosesc în continuare
   generarea aleatoare de nume din engine.js — vezi generateSquad().
   Sursă: paginile Wikipedia "[an] FIFA World Cup squads", verificate
   încrucișat jucător cu jucător.

   Notă: câțiva jucători sunt scriși cu numele complet (ex. "Ronaldo
   Nazário" în loc de doar "Ronaldo") ca să se potrivească exact cu
   intrarea corespunzătoare din LEGENDS (data.js) — asta declanșează
   boost-ul de "legendă" (rating sporit + bio) în generateSquad().
   ============================================================ */

